<template><div class="page"><div class="container checkout"><section><div class="eyebrow">03 — REVIEW</div><h1 class="h2">Ready to order?</h1><div class="review-card card"><div><b>Shipping</b><p>{{shipping.fullName}} · {{shipping.phone}}</p><p>{{shipping.line1}}, {{shipping.city}}, {{shipping.governorate}}</p></div><div><b>Payment</b><p>{{payment==='card'?'Card':'Cash on delivery'}}</p></div><div><b>Items</b><p v-for="i in cart.items" :key="i.id">{{i.name}} × {{i.quantity}}</p></div></div><button class="btn block" :disabled="submitting" @click="placeOrder">{{submitting?'Placing order…':'Place order'}}</button><p v-if="error" class="error">{{error}}</p></section><OrderSummary/></div></div></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import OrderSummary from './OrderSummary.vue';import {useCartStore} from '../../stores/cart';const router=useRouter(),cart=useCartStore(),submitting=ref(false),error=ref('');const shipping=computed(()=>JSON.parse(sessionStorage.getItem('vora_shipping')||'{}'));const payment=sessionStorage.getItem('vora_payment')||'card';async function placeOrder(){if(!cart.items.length)return;submitting.value=true;error.value='';try{await new Promise(r=>setTimeout(r,700));const id='VOR-'+Date.now().toString().slice(-7);const total=cart.total;cart.clear();sessionStorage.setItem('vora_last_order',JSON.stringify({id,total}));router.push(`/order/${id}/success`)}catch{error.value='Could not place the order. Please try again.'}finally{submitting.value=false}}</script>
<style scoped>.checkout{display:grid;grid-template-columns:1fr 360px;gap:50px;max-width:1050px}.review-card{padding:22px;margin:28px 0}.review-card>div{padding:15px 0;border-bottom:1px solid #eee}.review-card p{color:#666;line-height:1.5;margin:7px 0 0}.error{color:#c93434}@media(max-width:800px){.checkout{grid-template-columns:1fr}}</style>
